{
    "class": "AS3",
    "declaration": {
        "class": "ADC",
        "schemaVersion": "3.20.0",
        "Example_PIP": {
            "class": "Tenant",
            "A1": {
                "class": "Application",
                "service": {
                    "class": "Service_UDP",
                    "virtualPort": 53,
                    "virtualAddresses": [
                        "192.0.2.1"
                    ],
                    "profileProtocolInspection": {
                        "use": "DNSInspectionProfile"
                    }
                },
                "DNSInspectionProfile": {
                    "class": "Protocol_Inspection_Profile",
                    "remark": "Custom DNS Inspection Profile",
                    "collectAVRStats": true,
                    "enableComplianceChecks": true,
                    "enableSignatureChecks": true,
                    "autoAddNewInspections": true,
                    "autoPublish": true,
                    "services": [
                        {
                            "type": "dns",
                            "compliance": [
                                {
                                    "check": "dns_maximum_reply_length",
                                    "value": "1024"
                                },
                                {
                                    "check": "dns_disallowed_query_type",
                                    "action": "accept",
                                    "log": true,
                                    "value": "STATUS QUERY"
                                }
                            ],
                            "signature": [
                                {
                                    "check": "dns_dns_query_amplification_attempt",
                                    "action": "reject",
                                    "log": true
                                }
                            ]
                        }
                    ]
                },
                "service2": {
                    "class": "Service_UDP",
                    "virtualPort": 53,
                    "virtualAddresses": [
                        "192.0.2.2"
                    ],
                    "profileProtocolInspection": {
                        "bigip": "/Common/protocol_inspection_dns"
                    }
                }
            }
        }
    }
}

{
    "class": "ADC",
    "schemaVersion": "3.19.0",
    "id": "Idle_Timeout_Policy",
    "timeoutTenant": {
        "class": "Tenant",
        "timeoutApp": {
            "class": "Application",
            "timeoutGeneric": {
                "class": "Service_Generic",
                "virtualPort": 8080,
                "virtualAddresses": [
                    "192.0.2.141"
                ],
                "policyIdleTimeout": {
                    "use": "my_idle_timeout_policy"
                }
            },
            "my_idle_timeout_policy": {
                "class": "Idle_Timeout_Policy",
                "remark": "my policy remark",
                "rules": [
                    {
                        "name": "rule1",
                        "remark": "tcp all ports",
                        "protocol": "tcp",
                        "destinationPorts": [
                            "all-other"
                        ],
                        "idleTimeout": 120
                    },
                    {
                        "name": "rule2",
                        "remark": "udp port 9090",
                        "protocol": "udp",
                        "destinationPorts": [
                            9090
                        ],
                        "idleTimeout": 300
                    },
                    {
                        "name": "rule3",
                        "remark": "all other protocols",
                        "protocol": "all-other",
                        "idleTimeout": 40
                    },
                    {
                        "name": "rule4",
                        "remark": "non port 9090 udp",
                        "protocol": "udp",
                        "destinationPorts": [
                            "all-other"
                        ],
                        "idleTimeout": 60
                    }
                ]
            }
        }
    }
}

